<script setup lang="ts">
import {ref,watch} from 'vue'
import {useQuasar} from 'quasar'
import {api} from '../services/api'
import {useMonitor} from '../stores/monitor'
import type {Server} from '../types'
const props=defineProps<{modelValue:boolean;server?:Server|null}>(),emit=defineEmits(['update:modelValue','saved'])
const $q=useQuasar(),store=useMonitor(),saving=ref(false),error=ref('')
const name=ref(''),hostname=ref(''),environment=ref('Production'),probe=ref(''),mounts=ref('/'),services=ref('')
watch(()=>props.modelValue,value=>{if(value){const s=props.server;name.value=s?.name||'';hostname.value=s?.hostname||'';environment.value=s?.environment||'Production';probe.value=s?.probe_url||'';mounts.value=s?.filesystems.join(', ')||'/';services.value=s?.required_services.join(', ')||'';error.value=''}})
async function save(){saving.value=true;error.value='';try{const data={name:name.value,hostname:hostname.value,environment:environment.value,probe_url:probe.value,filesystems:mounts.value.split(',').map(x=>x.trim()).filter(Boolean),required_services:services.value.split(',').map(x=>x.trim()).filter(Boolean)};await api(props.server?`/servers/${props.server.id}`:'/servers',{method:props.server?'PATCH':'POST',body:JSON.stringify(data)});await store.refresh();emit('saved');emit('update:modelValue',false);$q.notify({message:props.server?'Server updated':'Server registered. Open its details to enroll the agent.',color:'positive'})}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
</script>
<template><q-dialog :model-value="modelValue" @update:model-value="emit('update:modelValue',$event)"><q-card class="form-dialog"><form @submit.prevent="save"><q-card-section><h2>{{server?'Edit server':'Add server'}}</h2><p class="muted">Register your infrastructure, then connect its agent.</p></q-card-section><q-card-section class="form-fields"><q-input v-model="name" outlined label="Server name" required maxlength="120"/><q-input v-model="hostname" outlined label="Hostname or IP address" required maxlength="253"/><q-select v-model="environment" :options="['Production','Staging','Development']" outlined label="Environment"/><q-input v-model="probe" outlined label="Independent probe URL (optional)" hint="HTTP(S) health endpoint or tcp://host:port. Private networks require backend allowlisting."/><q-input v-model="mounts" outlined label="Filesystem mount paths" hint="Comma-separated, for example /, /data"/><q-input v-model="services" outlined label="Required systemd services" hint="Comma-separated, for example nginx, mysql"/><div v-if="error" class="error-box" role="alert">{{error}}</div></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancel" v-close-popup/><q-btn type="submit" color="primary" unelevated no-caps label="Save server" :loading="saving"/></q-card-actions></form></q-card></q-dialog></template>
